using BlockEstate.Api.Data;
using BlockEstate.Api.Models;
using Microsoft.EntityFrameworkCore;
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddOpenApi();
builder.Services.AddDbContext<RegistryDbContext>(o => o.UseSqlServer(builder.Configuration.GetConnectionString("Registry")));
builder.Services.AddCors(o => o.AddPolicy("Frontend", p => p.WithOrigins(builder.Configuration.GetSection("Cors:AllowedOrigins").Get<string[]>() ?? ["http://localhost:5173"]).AllowAnyHeader().AllowAnyMethod()));
var app = builder.Build();
app.UseHttpsRedirection(); app.UseCors("Frontend"); if (app.Environment.IsDevelopment()) app.MapOpenApi();
app.MapGet("/api/health", () => Results.Ok(new { status = "ok", service = "BlockEstate Nexus API", note = "Health does not imply database or external integrations are ready." }));
app.MapGet("/api/properties", async (RegistryDbContext db, string? search, string? status, CancellationToken ct) => { IQueryable<PropertyRecord> q = db.Properties.AsNoTracking(); if (!string.IsNullOrWhiteSpace(search)) { var s = search.Trim(); q = q.Where(p => p.PropertyCode.Contains(s) || p.Title.Contains(s) || p.Location.Contains(s) || p.RecordedOwner.Contains(s) || p.ApplicationCode.Contains(s)); } if (!string.IsNullOrWhiteSpace(status)) q = q.Where(p => p.Status == status); return Results.Ok(await q.OrderByDescending(p => p.UpdatedAt).Take(250).ToListAsync(ct)); });
app.MapGet("/api/properties/{code}", async (string code, RegistryDbContext db, CancellationToken ct) => { var p = await db.Properties.AsNoTracking().SingleOrDefaultAsync(x => x.PropertyCode == code, ct); return p is null ? Results.NotFound(new { message = "Property record was not found." }) : Results.Ok(p); });
app.MapPost("/api/properties", async (CreatePropertyRequest r, RegistryDbContext db, CancellationToken ct) => { var errors = new Dictionary<string,string[]>(); void Required(string k,string? v,int max) { if (string.IsNullOrWhiteSpace(v)) errors[k] = ["This field is required."]; else if (v.Trim().Length > max) errors[k] = [$"Must be {max} characters or fewer."]; } Required("propertyCode",r.PropertyCode,40); Required("title",r.Title,180); Required("propertyType",r.PropertyType,80); Required("location",r.Location,240); Required("recordedOwner",r.RecordedOwner,160); Required("area",r.Area,80); if(errors.Count>0) return Results.ValidationProblem(errors); var code=r.PropertyCode.Trim(); if(await db.Properties.AnyAsync(p=>p.PropertyCode==code,ct)) return Results.Conflict(new {message="Property code already exists."}); var p=new PropertyRecord { PropertyCode=code, Title=r.Title.Trim(), PropertyType=r.PropertyType.Trim(), Location=r.Location.Trim(), RecordedOwner=r.RecordedOwner.Trim(), Area=r.Area.Trim(), Status="Under review", RiskLevel="Review", ApplicationCode=string.IsNullOrWhiteSpace(r.ApplicationCode)?$"APP-{DateTime.UtcNow:yyyy}-{Guid.NewGuid().ToString("N")[..8].ToUpperInvariant()}":r.ApplicationCode.Trim() }; db.Properties.Add(p); await db.SaveChangesAsync(ct); return Results.Created($"/api/properties/{p.PropertyCode}",p); });
app.MapPut("/api/properties/{code}/status", async (string code, UpdateStatusRequest r, RegistryDbContext db, CancellationToken ct) => { if(!new[]{"Under review","Verified","Action required"}.Contains(r.Status)) return Results.ValidationProblem(new Dictionary<string,string[]>{{"status",["Status is not supported."]}}); var p=await db.Properties.SingleOrDefaultAsync(x=>x.PropertyCode==code,ct); if(p is null) return Results.NotFound(); p.Status=r.Status; p.UpdatedAt=DateTimeOffset.UtcNow; await db.SaveChangesAsync(ct); return Results.Ok(p); });
app.Run();
public sealed record CreatePropertyRequest(string PropertyCode,string Title,string PropertyType,string Location,string RecordedOwner,string Area,string? ApplicationCode);
public sealed record UpdateStatusRequest(string Status);
